class Solution:
    def isUgly(self, n: int) -> bool:
        if n <= 0:
            return False
        for factor in [2, 3, 5]:
            while n % factor == 0:
                n //= factor
        return n == 1

class Solution {
public:
    bool isUgly(int n) {
        if (n <= 0) return false;
        int factors[] = {2, 3, 5};
        for (int f : factors) {
            while (n % f == 0) {
                n /= f;
            }
        }
        return n == 1;
    }
};

class Solution {
    public boolean isUgly(int n) {
        if (n <= 0) return false;
        int[] factors = {2, 3, 5};
        for (int f : factors) {
            while (n % f == 0) {
                n /= f;
            }
        }
        return n == 1;
    }
}

var isUgly = function(n) {
    if (n <= 0) return false;
    for (const f of [2, 3, 5]) {
        while (n % f === 0) {
            n /= f;
        }
    }
    return n === 1;
};
